import sys
from sympy import symbols, simplify
from galgebra.ga import Ga

def main():
    # 1. Model isospin SU(2) using the geometric algebra Cl(3,0) (Pauli algebra).
    isospin_ga = Ga('tau_1 tau_2 tau_3', g=[1, 1, 1])
    t1, t2, t3 = isospin_ga.mv()
    I = t1 * t2 * t3  # Pseudoscalar

    # 2. Represent proton and neutron states as spinors (idempotents).
    # Using the standard idempotent formulation in Pauli algebra Cl(3,0)
    rho_p = (1 + t3) / 2  # Proton projector / idempotent
    rho_n = (1 - t3) / 2  # Neutron projector
    
    # State basis in the right ideal generated by rho_p
    p_state = rho_p
    n_state = t1 * rho_p

    # 3. Model the isospin lowering/raising operators (charge exchange).
    tau_plus = (t1 + I * t2) / 2
    tau_minus = (t1 - I * t2) / 2

    # Check operations
    # tau_plus |n> = |p>
    test_1 = tau_plus * n_state
    diff_1 = simplify((test_1 - p_state).obj)
    pass_1 = (diff_1 == 0)

    # tau_minus |p> = |n>
    test_2 = tau_minus * p_state
    diff_2 = simplify((test_2 - n_state).obj)
    pass_2 = (diff_2 == 0)

    # tau_plus |p> = 0
    test_3 = tau_plus * p_state
    diff_3 = simplify(test_3.obj)
    pass_3 = (diff_3 == 0)

    # tau_minus |n> = 0
    test_4 = tau_minus * n_state
    diff_4 = simplify(test_4.obj)
    pass_4 = (diff_4 == 0)

    # 4. Formulates the electromagnetic transition operator as a geometric product.
    # Q = (1 + tau_3) / 2 = rho_p
    Q = rho_p
    
    # Q |p> = |p>
    test_q_p = Q * p_state
    pass_q_p = simplify((test_q_p - p_state).obj) == 0

    # Q |n> = 0
    test_q_n = Q * n_state
    pass_q_n = simplify(test_q_n.obj) == 0

    # 5. Verifies the isospin symmetry breaking term (Coulomb repulsion) geometrically.
    # The Coulomb interaction is proportional to Q. It breaks SU(2) isospin symmetry
    # because Q does not commute with tau_1 and tau_2 (or tau_plus/tau_minus).
    comm_Q_t1 = Q * t1 - t1 * Q
    pass_sym_break = simplify(comm_Q_t1.obj) != 0
    
    all_passed = pass_1 and pass_2 and pass_3 and pass_4 and pass_q_p and pass_q_n and pass_sym_break
    
    if all_passed:
        print("PASS")
    else:
        print("FAIL")
        print(f"pass_1 (tau_+|n> == |p>): {pass_1}")
        print(f"pass_2 (tau_-|p> == |n>): {pass_2}")
        print(f"pass_3 (tau_+|p> == 0): {pass_3}")
        print(f"pass_4 (tau_-|n> == 0): {pass_4}")
        print(f"pass_q_p (Q|p> == |p>): {pass_q_p}")
        print(f"pass_q_n (Q|n> == 0): {pass_q_n}")
        print(f"pass_sym_break ([Q, t1] != 0): {pass_sym_break}")

if __name__ == '__main__':
    main()
